<!-- Shared, read-only capability explanation for the design preview. -->
<template><section class="sw-capabilities" :class="{limited}" data-storage-capabilities><details><summary><span>{{limited?'部分操作暂不可用':'系统存储能力'}}</span><small>{{limited?(issues.length+levelIssues.length)+' 项待处理':'已确认 · 示例'}}</small></summary><p>按本机能力开放操作。系统能力与硬盘是否空闲、阵列是否健康分别检查。</p><ul><li v-for="feature in features" :key="feature"><strong>{{featureNames[feature]}}<small>{{stateNames[capabilities.features[feature].state]}}</small></strong><template v-if="featureIssue(feature)"><p>{{capabilities.features[feature].reason}}</p><p>{{capabilities.features[feature].next}}</p></template></li></ul><p v-for="entry in levelIssues" :key="entry[0]">{{entry[0].replace('raid','RAID ')}}：{{entry[1].reason}}</p><p>检测时间：{{capabilities.sampledAt}} · 产品原型示例</p><button @click="recheckCapabilities">重新检测（演示）</button></details><p v-if="issues.length" role="status">{{featureIssue(issues[0])}} <span>已有记录保留供查看；当前状态需重新核实。</span></p></section></template>
<script setup lang="ts">
import {computed} from 'vue'
import {capabilities,featureNames,stateNames,featureIssue,recheckCapabilities,type Feature} from './storageCapabilitiesPrototype'
const props=defineProps<{features:Feature[]}>()
const levelIssues=computed(()=>props.features.includes('raid')?Object.entries(capabilities.levels).filter(([,c])=>c.state!=='ready'):[])
const limited=computed(()=>!!issues.value.length||!!levelIssues.value.length)
const issues=computed(()=>props.features.filter(f=>!!featureIssue(f)))
</script>
<style>
.sw-capabilities{margin:12px 0;border:1px solid var(--home-border,#dbe4ef);border-radius:12px;padding:12px 16px;background:var(--home-card-bg,#fff);font-size:13px;line-height:1.6;color:var(--home-text,#25364a)}.sw-capabilities.limited{border-color:var(--home-warning,#cf9c48)}.sw-capabilities summary{cursor:pointer;display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-weight:600}.sw-capabilities small{font-size:12px;font-weight:400;opacity:.75;margin-left:10px}.sw-capabilities p{margin:8px 0;overflow-wrap:anywhere}.sw-capabilities ul{list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}.sw-capabilities li{padding:10px;border:1px solid var(--home-border,#dbe4ef);border-radius:8px}.sw-capabilities li p{font-size:12px}.sw-capabilities button{cursor:pointer}.sw-capabilities.limited>p{margin-bottom:0}.lh-prototype .lh-purpose:disabled,.sw .lh-purpose:disabled{opacity:1;cursor:not-allowed;background:var(--lh-soft,#f4f6fa);color:var(--lh-muted,#697386)}.rs-levels label:has(input:disabled){opacity:1;cursor:not-allowed;color:var(--sw-muted,#697386)}.sp-capability-reason{display:block;color:var(--lh-muted,var(--sw-muted,#697386));font-size:12px;line-height:1.6;margin-top:8px}.sw-capabilities{background:var(--sw-panel,var(--home-card-bg,#fff));color:var(--sw-text,var(--home-text,#25364a))}
</style>
